<?php if (!defined('BASEPATH')) exit('No direct script access allowed');class mlabmodel extends CI_Model {    function fnGetLabInfo($VarLab = '', $VarStatus = '', $VarId = '', $VarCompanyId = '') {        $this->db->select('id,labname,updatedby,status,datecreated,dateupdated'); // Select field        $this->db->from(KN_MASTER_LAB);        // if ($VarStatus <> '') {        //     $this->db->where_in('status', array($VarStatus));        // } else {        //     $this->db->where_in('status', array(1, 2));        // }        if ($VarId <> '') {            $ArrWhere['id'] = $VarId;        }        if ($VarLab <> '') {            $ArrWhere['labname'] = trim($VarLab);        }        if ($VarCompanyId <> '') {            //$this->db->where_not_in('id', array($VarId));            $ArrWhere['companyid'] = $VarCompanyId;        }        if (@count($ArrWhere) >= 1) {            $this->db->where($ArrWhere);        }        $ArrResultList = $this->db->get()->result_array();        return $ArrResultList;    }    function fnCheckLab($VarLab = '', $VarId = '', $VarCompanyId = '') {        $this->db->from(KN_MASTER_LAB);        //$ArrWhere = array('status' => "1");        if ($VarId <> '') {            $this->db->where_not_in('id', array($VarId));        }        if ($VarLab <> '') {            $ArrWhere['labname'] = trim($VarLab);        }        if ($VarCompanyId <> '') {            $ArrWhere['companyid'] = $VarCompanyId;        }        //$ArrWhere['labname'] = $VarLab;        $countAll = $this->db->where($ArrWhere)->count_all_results();        return $countAll;    }    function saveLabInfo($ArrUpdateData) {        $VarId = $ArrUpdateData['id'];        if ($VarId == "") {            $ArrCheckExist = $this->fnGetLabInfo($ArrUpdateData['labname'], 1, '', $ArrUpdateData['companyid']);            if (empty($ArrCheckExist)) {                unset($ArrUpdateData['id']);                $this->db->insert(KN_MASTER_LAB, $ArrUpdateData);                $VarId = $this->db->insert_id();                $ArrResult['errcode'] = 1;                $ArrResult['msg'] = '';                $ArrResult['id'] = $VarId;                $ArrResult['eid'] = urlencode(base64_encode($VarId));            } else {                $ArrResult['errcode'] = -1;                $ArrResult['msg'] = "This lab parameter already exists";            }        } else {            $ArrCheckExist = $this->fnCheckLab($ArrUpdateData['labname'], $VarId, $ArrUpdateData['companyid']);            if (empty($ArrCheckExist)) {                if ($this->db->update(KN_MASTER_LAB, $ArrUpdateData, array('id' => $VarId))) {                    $ArrResult['errcode'] = 1;                    $ArrResult['msg'] = '';                    $ArrResult['id'] = $VarId;                    $ArrResult['eid'] = urlencode(base64_encode($VarId));                } else {                    $ArrResult['errcode'] = -1;                    $ArrResult['msg'] = 'Invalid Data';                }            } else {                $ArrResult['errcode'] = -1;                $ArrResult['msg'] = "This lab parameter already exists";            }        }        return $ArrResult;    }    function fnCountLab($VarLab = '', $VarStatus = '', $VarAfilter = '') {        $ArrUserLoggedInfo = fnGetUserLoggedInfo('1');        $VarCompanyId      = $ArrUserLoggedInfo['companyid'];        $ArrWhere          = array();        if ($VarLab <> '') {            $ArrWhere[] = "ln.labname like '%" . $VarLab . "%'";        }        if ($VarStatus <> '') {            $ArrWhere[] = "ln.status=" . $VarStatus;        } else {            $ArrWhere[] = "ln.status in(1,2)";        }        if ($VarAfilter <> '') {            $ArrWhere[] = "ln.labname like '" . $VarAfilter . "%'";        }        $VarWhere = '';        if (@$ArrWhere[0] <> '') {            $VarWhere = implode(" and ", $ArrWhere) . " AND ln.companyid = '" . $VarCompanyId . "' ";        }        $VarSqlLab = "SELECT count(1) as trec  FROM " . KN_MASTER_LAB . " AS ln LEFT JOIN " . KN_USERS . " AS u ON ln.updatedby = u.id WHERE " . $VarWhere;        $ObjRows = $this->db->query($VarSqlLab)->row();        return $ObjRows->trec;    }    function fnListLab($VarLab = '', $VarStatus = '', $VarLimit = 10, $offset = 0, $VarSortBy, $VarSortOrder, $VarAfilter = '') {        $ArrUserLoggedInfo = fnGetUserLoggedInfo('1');        $VarCompanyId      = $ArrUserLoggedInfo['companyid'];        $VarSortOrder      = ($VarSortOrder == 'desc') ? 'desc' : 'asc';        $VarSortCols = array('ln.labname','ln.status','u.contactname','ln.dateupdated');        $VarSortBy = (in_array($VarSortBy, $VarSortCols)) ? $VarSortBy : 'ln.dateupdated';        $VarLimitInfo = $VarLimit;        if ($offset >= 1) {            $VarLimitInfo = $offset . "," . $VarLimit;        }        $ArrWhere = array();        if ($VarLab <> '') {            $ArrWhere[] = "ln.labname like '%" . $VarLab . "%'";        }        if ($VarStatus <> '') {            $ArrWhere[] = "ln.status=" . $VarStatus;        } else {            $ArrWhere[] = "ln.status in(1,2)";        }        if ($VarAfilter <> '') {            $ArrWhere[] = "ln.labname like '" . $VarAfilter . "%'";        }        $VarWhere = '';        if (@$ArrWhere[0] <> '') {            $VarWhere = implode(" and ", $ArrWhere) . " AND ln.companyid = '" . $VarCompanyId . "' ";        }        // removed this line . " limit " . $VarLimitInfo in below query        $VarSqlLab = "SELECT ln.id,ln.labname,u.contactname,ln.datecreated,ln.dateupdated,ln.status FROM " . KN_MASTER_LAB . " AS ln LEFT JOIN " . KN_USERS . " AS u ON ln.updatedby = u.id WHERE " . $VarWhere . " order by " . $VarSortBy . " " . $VarSortOrder;        $ObjResult = $this->db->query($VarSqlLab);        return $ObjResult;    }    function fnChangeComStat($checkboxids, $optvalue) {        $Arrids = json_decode($checkboxids, true);        $this->db->where_in('id', $Arrids);        if ($this->db->update(KN_MASTER_LAB, array('status' => $optvalue))) {            return true;        }        return false;    }}